/**
 * Returns an optimized lightweight static WebP version if available,
 * otherwise falls back to the original source.
 */
export function getOptimizedImageUrl(src?: string | null): string {
  if (!src) return "/placeholder.svg";
  
  if (OPTIMIZED_IMAGE_MAP[src]) {
    return OPTIMIZED_IMAGE_MAP[src];
  }

  const trimmed = src.trim();
  if (OPTIMIZED_IMAGE_MAP[trimmed]) {
    return OPTIMIZED_IMAGE_MAP[trimmed];
  }

  return src;
}
